     1→package config
     2→
     3→import (
     4→	"errors"
     5→	"fmt"
     6→	"log/slog"
     7→	"maps"
     8→	"os"
     9→	"regexp"
    10→	"slices"
    11→	"strings"
    12→
    13→	"gopkg.in/yaml.v3"
    14→)
    15→
    16→type Config struct {
    17→	Server Server            `yaml:"server"          json:"server"`
    18→	Apps   map[string]App    `yaml:"apps,omitempty"  json:"apps,omitempty"`
    19→	Stacks map[string]Stack  `yaml:"stacks,omitempty" json:"stacks,omitempty"`
    20→}
    21→
    22→type Server struct {
    23→	Name         string `yaml:"name"          json:"name"`
    24→	DeployDomain string `yaml:"deploy_domain" json:"deploy_domain"`
    25→	StacksDir    string `yaml:"stacks_dir"    json:"stacks_dir"`
    26→	GithubToken  string `yaml:"github_token"  json:"github_token,omitempty"`
    27→}
    28→
    29→type App struct {
    30→	Repo     string         `yaml:"repo"              json:"repo"`
    31→	Branch   string         `yaml:"branch"            json:"branch"`
    32→	Domain   string         `yaml:"domain"            json:"domain"`
    33→	EnvFile  string         `yaml:"env_file,omitempty"  json:"env_file,omitzero"`
    34→	Compose  string         `yaml:"compose,omitempty"   json:"compose,omitzero"`
    35→	Override string         `yaml:"override,omitempty"  json:"override,omitzero"`
    36→	Secrets  []SecretRef    `yaml:"secrets,omitempty"   json:"secrets,omitzero"`
    37→	Preview  *PreviewConfig `yaml:"preview,omitempty"   json:"preview,omitzero"`
    38→}
    39→
    40→type Stack struct {
    41→	Path         string `yaml:"path"                    json:"path"`
    42→	Domain       string `yaml:"domain"                  json:"domain"`
    43→	AutoDeploy   bool   `yaml:"auto_deploy"             json:"auto_deploy,omitzero"`
    44→	UpdateScript string `yaml:"update_script,omitempty" json:"update_script,omitzero"`
    45→}
    46→
    47→type SecretRef struct {
    48→	Key    string `yaml:"key"    json:"key"`
    49→	Type   string `yaml:"type"   json:"type"`
    50→	Target string `yaml:"target" json:"target"`
    51→}
    52→
    53→type PreviewConfig struct {
    54→	Enabled bool   `yaml:"enabled"           json:"enabled,omitzero"`
    55→	Domain  string `yaml:"domain,omitempty"  json:"domain,omitzero"`
    56→}
    57→
    58→var envVarRe = regexp.MustCompile(`\$\{([^}]+)\}`)
    59→
    60→// Load reads the YAML config file at path, applies defaults, expands env vars,
    61→// and validates the result. Returns a descriptive error on any failure.
    62→func Load(path string) (*Config, error) {
    63→	data, err := os.ReadFile(path)
    64→	if err != nil {
    65→		return nil, fmt.Errorf("reading config %s: %w", path, err)
    66→	}
    67→
    68→	var cfg Config
    69→	if err := yaml.Unmarshal(data, &cfg); err != nil {
    70→		var typeErr *yaml.TypeError
    71→		if errors.As(err, &typeErr) {
    72→			return nil, fmt.Errorf("config %s: %w", path, typeErr)
    73→		}
    74→		return nil, fmt.Errorf("config %s: %w", path, err)
    75→	}
    76→
    77→	// Expand ${VAR} in github_token only.
    78→	original := cfg.Server.GithubToken
    79→	cfg.Server.GithubToken = envVarRe.ReplaceAllStringFunc(cfg.Server.GithubToken, func(match string) string {
    80→		varName := match[2 : len(match)-1]
    81→		return os.Getenv(varName)
    82→	})
    83→	if cfg.Server.GithubToken == "" && strings.Contains(original, "${") {
    84→		slog.Warn("github_token expanded to empty string", "original", original)
    85→	}
    86→
    87→	// Apply defaults for app fields.
    88→	for name, app := range cfg.Apps {
    89→		if app.Branch == "" {
    90→			app.Branch = "main"
    91→		}
    92→		if app.Compose == "" {
    93→			app.Compose = "compose.yml"
    94→		}
    95→		cfg.Apps[name] = app
    96→	}
    97→
    98→	if err := validate(&cfg); err != nil {
    99→		return nil, err
   100→	}
   101→
   102→	return &cfg, nil
   103→}
   104→
   105→func validate(cfg *Config) error {
   106→	if cfg.Server.Name == "" {
   107→		return errors.New("server.name is required")
   108→	}
   109→	if cfg.Server.DeployDomain == "" {
   110→		return errors.New("server.deploy_domain is required")
   111→	}
   112→	if cfg.Server.StacksDir == "" {
   113→		return errors.New("server.stacks_dir is required")
   114→	}
   115→
   116→	// Collect all domains to detect duplicates across apps and stacks.
   117→	domains := make(map[string]string) // domain -> "app:name" or "stack:name"
   118→
   119→	for _, name := range slices.Sorted(maps.Keys(cfg.Apps)) {
   120→		app := cfg.Apps[name]
   121→		if app.Repo == "" {
   122→			return fmt.Errorf("app %q: repo is required", name)
   123→		}
   124→		if app.Domain == "" {
   125→			return fmt.Errorf("app %q: domain is required", name)
   126→		}
   127→		if prev, exists := domains[app.Domain]; exists {
   128→			return fmt.Errorf("app %q: domain %q already used by %s", name, app.Domain, prev)
   129→		}
   130→		domains[app.Domain] = "app:" + name
   131→
   132→		for i, sec := range app.Secrets {
   133→			if sec.Type != "env" && sec.Type != "docker-secret" {
   134→				return fmt.Errorf("app %q: secrets[%d]: type must be \"env\" or \"docker-secret\", got %q", name, i, sec.Type)
   135→			}
   136→		}
   137→
   138→		if app.Preview != nil && app.Preview.Enabled {
   139→			if app.Preview.Domain == "" {
   140→				return fmt.Errorf("app %q: preview.domain is required when preview.enabled is true", name)
   141→			}
   142→			if !strings.Contains(app.Preview.Domain, "*") {
   143→				return fmt.Errorf("app %q: preview.domain must contain a wildcard (*)", name)
   144→			}
   145→		}
   146→	}
   147→
   148→	for _, name := range slices.Sorted(maps.Keys(cfg.Stacks)) {
   149→		stack := cfg.Stacks[name]
   150→		if stack.Path == "" {
   151→			return fmt.Errorf("stack %q: path is required", name)
   152→		}
   153→		if stack.Domain == "" {
   154→			return fmt.Errorf("stack %q: domain is required", name)
   155→		}
   156→		if prev, exists := domains[stack.Domain]; exists {
   157→			return fmt.Errorf("stack %q: domain %q already used by %s", name, stack.Domain, prev)
   158→		}
   159→		domains[stack.Domain] = "stack:" + name
   160→	}
   161→
   162→	return nil
   163→}
