   159→// gitSync clones the repo on first deploy or fetch+reset on subsequent ones.
   160→func (d *Deployer) gitSync(ctx context.Context, appDir string, app config.App) error {
   161→	repoDir := filepath.Join(appDir, "repo")
   162→	cloneURL := buildCloneURL(d.Config.Server.GithubToken, app.Repo)
   163→
   164→	_, err := os.Stat(repoDir)
   165→	if os.IsNotExist(err) {
   166→		d.Logger.Info("git clone", "repo", app.Repo, "branch", app.Branch)
   167→		return runCmd(ctx, d.Logger, "", "git",
   168→			"clone", "--branch", app.Branch,
   169→			"--single-branch", "--depth", "1",
   170→			cloneURL, repoDir,
   171→		)
   172→	}
   173→	if err != nil {
   174→		return fmt.Errorf("stat repo dir: %w", err)
   175→	}
   176→
   177→	d.Logger.Info("git fetch+reset", "repo", app.Repo, "branch", app.Branch)
   178→	if err := runCmd(ctx, d.Logger, repoDir, "git", "fetch", "origin", app.Branch); err != nil {
   179→		return err
   180→	}
   181→	return runCmd(ctx, d.Logger, repoDir, "git", "reset", "--hard", "origin/"+app.Branch)
   182→}
   183→
   184→// buildCloneURL returns the HTTPS clone URL, embedding the token if provided.
   185→func buildCloneURL(token, repo string) string {
   186→	if token != "" {
   187→		return fmt.Sprintf("https://%s@github.com/%s.git", token, repo)
   188→	}
   189→	return fmt.Sprintf("https://github.com/%s.git", repo)
   190→}
   191→
   192→// writeEnvFile writes KEY=value pairs to .env, sorted by key.
   193→func writeEnvFile(root *os.Root, envVars map[string]string) error {
   194→	f, err := root.OpenFile(".env", os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
   195→	if err != nil {
   196→		return err
   197→	}
   198→	defer f.Close()
   199→	for _, key := range slices.Sorted(maps.Keys(envVars)) {
   200→		if _, err := fmt.Fprintf(f, "%s=%s\n", key, envVars[key]); err != nil {
   201→			return err
   202→		}
   203→	}
   204→	return nil
   205→}
   206→
   207→// writeSecret writes a docker secret value to a file in the secrets root.
   208→func writeSecret(root *os.Root, name, value string) error {
   209→	f, err := root.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
   210→	if err != nil {
   211→		return err
   212→	}
   213→	defer f.Close()
   214→	_, err = f.WriteString(value)
   215→	return err
   216→}
