   327→// detectServiceInfo parses a compose file to find the main service name and port.
   328→// Prefers a service named "app", then appName, then the first alphabetically.
   329→func detectServiceInfo(composeFilePath, appName string) (serviceName, port string, err error) {
   330→	data, err := os.ReadFile(composeFilePath)
   331→	if err != nil {
   332→		return "", "", err
   333→	}
   334→
   335→	var mc minimalCompose
   336→	if err := yaml.Unmarshal(data, &mc); err != nil {
   337→		return "", "", err
   338→	}
   339→
   340→	if len(mc.Services) == 0 {
   341→		return "app", "3000", nil
   342→	}
   343→
   344→	names := slices.Sorted(maps.Keys(mc.Services))
   345→	serviceName = names[0]
   346→	for _, n := range names {
   347→		if n == "app" || n == appName {
   348→			serviceName = n
   349→			break
   350→		}
   351→	}
   352→
   353→	port = extractFirstPort(mc.Services[serviceName])
   354→	if port == "" {
   355→		port = "3000"
   356→	}
   357→	return serviceName, port, nil
   358→}
   359→
   360→func extractFirstPort(svc minimalService) string {
   361→	for _, v := range svc.Expose {
   362→		if p := portFromAny(v); p != "" {
   363→			return p
   364→		}
   365→	}
   366→	for _, v := range svc.Ports {
   367→		if p := portFromAny(v); p != "" {
   368→			return p
   369→		}
   370→	}
   371→	return ""
   372→}
   373→
   374→func portFromAny(v any) string {
   375→	switch val := v.(type) {
   376→	case string:
   377→		// "3000", "3000:3000", "0.0.0.0:80:3000"
   378→		parts := strings.Split(val, ":")
   379→		p := strings.TrimSpace(parts[len(parts)-1])
   380→		return p
   381→	case int:
   382→		return fmt.Sprintf("%d", val)
   383→	case map[string]any:
   384→		// long form: {target: 3000, published: 3000}
   385→		if t, ok := val["target"]; ok {
   386→			return portFromAny(t)
   387→		}
   388→	}
   389→	return ""
   390→}
   391→
   392→// deepMerge recursively merges overlay into base. Overlay wins on conflict
   393→// unless both values are maps, in which case they are merged recursively.
   394→func deepMerge(base, overlay map[string]any) map[string]any {
   395→	result := make(map[string]any, len(base))
   396→	for k, v := range base {
   397→		result[k] = v
   398→	}
   399→	for k, v := range overlay {
   400→		if bv, ok := result[k]; ok {
   401→			if bMap, ok := bv.(map[string]any); ok {
   402→				if oMap, ok := v.(map[string]any); ok {
   403→					result[k] = deepMerge(bMap, oMap)
   404→					continue
   405→				}
   406→			}
   407→		}
   408→		result[k] = v
   409→	}
   410→	return result
   411→}
   412→
   413→// runCompose executes docker compose up -d --build --remove-orphans.
   414→func (d *Deployer) runCompose(ctx context.Context, appDir, appName, composeFile string) error {
   415→	repoDir := filepath.Join(appDir, "repo")
   416→	overrideFile := filepath.Join(appDir, "compose.override.yml")
   417→	d.Logger.Info("compose up", "app", appName, "project", "herald-"+appName)
   418→	return runCmd(ctx, d.Logger, repoDir,
   419→		"docker", "compose",
   420→		"--project-name", "herald-"+appName,
   421→		"-f", composeFile,
   422→		"-f", overrideFile,
   423→		"up", "-d", "--build", "--remove-orphans",
   424→	)
   425→}
   426→
   427→// runCmd executes a command, logs stdout/stderr line-by-line, and returns an
   428→// error on non-zero exit.
   429→func runCmd(ctx context.Context, logger *slog.Logger, dir string, name string, args ...string) error {
   430→	cmd := exec.CommandContext(ctx, name, args...)
   431→	if dir != "" {
   432→		cmd.Dir = dir
   433→	}
   434→
   435→	var stdout, stderr bytes.Buffer
   436→	cmd.Stdout = &stdout
   437→	cmd.Stderr = &stderr
   438→
   439→	start := time.Now()
   440→	runErr := cmd.Run()
   441→	dur := time.Since(start).Round(time.Millisecond)
   442→
   443→	logLines := func(output string, level slog.Level) {
   444→		for line := range strings.Lines(output) {
   445→			line = strings.TrimRight(line, "\n\r")
   446→			if line != "" {
   447→				logger.Log(ctx, level, line, "cmd", name)
   448→			}
   449→		}
   450→	}
   451→
   452→	logLines(stdout.String(), slog.LevelInfo)
   453→	if stderr.Len() > 0 {
   454→		logLines(stderr.String(), slog.LevelWarn)
   455→	}
   456→
   457→	if runErr != nil {
   458→		return fmt.Errorf("%s: %w (duration: %s)", name, runErr, dur)
   459→	}
   460→
   461→	logger.Info("command completed", "cmd", name, "duration", dur)
   462→	return nil
   463→}
