   217→
   218→// --- Compose override generation ---
   219→
   220→type composeOverride struct {
   221→	Services map[string]serviceOverride `yaml:"services"`
   222→	Networks map[string]networkDef      `yaml:"networks,omitempty"`
   223→	Secrets  map[string]secretFileDef   `yaml:"secrets,omitempty"`
