   226→type serviceOverride struct {
   227→	Labels   map[string]string `yaml:"labels,omitempty"`
   228→	EnvFile  []string          `yaml:"env_file,omitempty"`
   229→	Secrets  []string          `yaml:"secrets,omitempty"`
   230→	Networks []string          `yaml:"networks,omitempty"`
