   233→type networkDef struct {
   234→	External bool `yaml:"external"`
   235→}
   236→
   237→type secretFileDef struct {
   238→	File string `yaml:"file"`
   239→}
   240→
   241→type minimalCompose struct {
   242→	Services map[string]minimalService `yaml:"services"`
   243→}
