   245→type minimalService struct {
   246→	Expose []any `yaml:"expose"`
   247→	Ports  []any `yaml:"ports"`
   248→}
   249→
   250→func (d *Deployer) generateOverride(
   251→	root *os.Root,
   252→	appDir, appName string,
   253→	app config.App,
   254→	repoDir, composeFile string,
   255→	dockerSecrets map[string]string,
   256→) error {
   257→	// Detect service name and port from the app's compose file.
   258→	serviceName, port, err := detectServiceInfo(filepath.Join(repoDir, composeFile), appName)
   259→	if err != nil {
   260→		d.Logger.Warn("could not detect service info, using defaults",
   261→			"app", appName, "error", err)
   262→		serviceName = "app"
   263→		port = "3000"
   264→	}
   265→
   266→	svc := serviceOverride{
   267→		Labels: map[string]string{
   268→			"caddy":               app.Domain,
   269→			"caddy.reverse_proxy": fmt.Sprintf("{{upstreams %s}}", port),
   270→		},
   271→		Networks: []string{"caddy"},
   272→	}
   273→
   274→	if app.EnvFile != "" {
   275→		svc.EnvFile = []string{app.EnvFile}
   276→	}
   277→
   278→	secretNames := slices.Sorted(maps.Keys(dockerSecrets))
   279→	if len(secretNames) > 0 {
   280→		svc.Secrets = secretNames
   281→	}
   282→
   283→	override := composeOverride{
   284→		Services: map[string]serviceOverride{serviceName: svc},
   285→		Networks: map[string]networkDef{"caddy": {External: true}},
   286→	}
   287→
   288→	if len(secretNames) > 0 {
   289→		override.Secrets = make(map[string]secretFileDef, len(secretNames))
   290→		for _, name := range secretNames {
   291→			override.Secrets[name] = secretFileDef{
   292→				File: filepath.Join(appDir, "secrets", name),
   293→			}
   294→		}
   295→	}
   296→
   297→	data, err := yaml.Marshal(override)
   298→	if err != nil {
   299→		return fmt.Errorf("marshaling override: %w", err)
   300→	}
   301→
   302→	// If app has inline override YAML, deep-merge it.
   303→	if app.Override != "" {
   304→		var baseMap, overlayMap map[string]any
   305→		if err := yaml.Unmarshal(data, &baseMap); err != nil {
   306→			return fmt.Errorf("re-parsing generated override: %w", err)
   307→		}
   308→		if err := yaml.Unmarshal([]byte(app.Override), &overlayMap); err != nil {
   309→			return fmt.Errorf("parsing app override YAML: %w", err)
   310→		}
   311→		merged := deepMerge(baseMap, overlayMap)
   312→		data, err = yaml.Marshal(merged)
   313→		if err != nil {
   314→			return fmt.Errorf("marshaling merged override: %w", err)
   315→		}
   316→	}
   317→
   318→	f, err := root.OpenFile("compose.override.yml", os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0644)
   319→	if err != nil {
   320→		return err
